function validate([scores, edges]) {
  const n = Array.isArray(scores) ? scores.length : 0;
  if (n < 4 || n > 50000) return 'scores needs 4 to 50000 values.';
  if (scores.some(s => !Number.isInteger(s) || s < 1 || s > 100000000)) return 'Each score is between 1 and 10^8.';
  if (!Array.isArray(edges) || edges.length > 50000) return 'edges has at most 50000 entries.';
  const seen = new Set();
  for (const edge of edges) {
    if (!Array.isArray(edge) || edge.length !== 2) return 'Each edge is a pair [a, b].';
    const [u, v] = edge;
    if (!Number.isInteger(u) || !Number.isInteger(v) || u < 0 || v < 0 || u >= n || v >= n) return 'Edge ends must be node labels 0 to n - 1.';
    if (u === v) return 'An edge must join two different nodes.';
    const key = Math.min(u, v) * n + Math.max(u, v);
    if (seen.has(key)) return 'No edge may appear twice.';
    seen.add(key);
  }
  return null;
}

