function maximumScore(scores, edges) {
  const n = scores.length;
  const neighbors = Array.from({ length: n }, () => []);
  for (const [u, v] of edges) {
    neighbors[u].push(v);
    neighbors[v].push(u);
  }
  const top = [];
  for (let node = 0; node < n; node++) {
    neighbors[node].sort((x, y) => scores[y] - scores[x]);
    top.push(neighbors[node].slice(0, 3));
  }
  let best = -1;
  for (const [b, c] of edges) {
    for (const a of top[b]) {
      if (a === c) {
        continue;
      }
      for (const d of top[c]) {
        if (d === b || d === a) {
          continue;
        }
        best = Math.max(best, scores[a] + scores[b] + scores[c] + scores[d]);
      }
    }
  }
  return best;
}

