function maximumScore(scores, edges) {
  // Try every ordered choice of 4 distinct nodes and keep those whose consecutive pairs are edges.
  const n = scores.length;
  const linked = new Set(edges.map(([u, v]) => u * n + v).concat(edges.map(([u, v]) => v * n + u)));
  let answer = -1;
  for (let p = 0; p < n; p++)
    for (let q = 0; q < n; q++) {
      if (q === p || !linked.has(p * n + q)) continue;
      for (let r = 0; r < n; r++) {
        if (r === p || r === q || !linked.has(q * n + r)) continue;
        for (let s = 0; s < n; s++) {
          if (s === p || s === q || s === r || !linked.has(r * n + s)) continue;
          answer = Math.max(answer, scores[p] + scores[q] + scores[r] + scores[s]);
        }
      }
    }
  return answer;
}

