function generate(rand, size) {
  const large = size === 'large';
  const n = large ? 1000 + Math.floor(rand() * 1001) : 4 + Math.floor(rand() * 5);
  const top = large || rand() < 0.3 ? 100000000 : 10;
  const scores = Array.from({ length: n }, () => (rand() < 0.1 ? top : 1 + Math.floor(rand() * top)));
  const seen = new Set();
  const edges = [];
  const add = (u, v) => {
    if (u === v) return;
    const key = Math.min(u, v) * n + Math.max(u, v);
    if (seen.has(key)) return;
    seen.add(key);
    edges.push(rand() < 0.5 ? [u, v] : [v, u]);
  };
  const shape = Math.floor(rand() * 4);
  if (large) {
    const hubs = 1 + Math.floor(rand() * 5);
    const want = 1500 + Math.floor(rand() * 501);
    // A few busy hubs plus random edges, so some nodes have many neighbours to rank.
    for (let tries = 0; edges.length < want && tries < 20 * want; tries++) {
      const u = shape < 2 ? Math.floor(rand() * hubs) : Math.floor(rand() * n);
      add(u, Math.floor(rand() * n));
    }
    return [scores, edges];
  }
  if (shape === 0) {
    for (let v = 1; v < n; v++) add(0, v);
    if (rand() < 0.5) add(1 + Math.floor(rand() * (n - 1)), 1 + Math.floor(rand() * (n - 1)));
  } else if (shape === 1) {
    for (let v = 1; v < n; v++) if (rand() < 0.7) add(v - 1, v);
  } else {
    const chance = shape === 2 ? 0.25 : 0.6;
    for (let u = 0; u < n; u++) for (let v = u + 1; v < n; v++) if (rand() < chance) add(u, v);
  }
  return [scores, edges];
}
